D.save = function(){ try{ localStorage.setItem('damus-v1',JSON.stringify(D.S)); }catch(e){} };
D.load = function(){ var s=null; try{ s=JSON.parse(localStorage.getItem('damus-v1')); }catch(e){} if(!s||!s.events){ var b=D.baseline(); s={events:b.events,forecasts:b.forecasts,queue:[],user:'',theme:'dark',seq:b.events.length,fseq:b.forecasts.length,model:D.ai.model,search:true,brief:''}; } s.applied=s.applied||{}; D.S=s; D.ai.model=s.model||D.ai.model; D.ai.search=s.search!==false; };
D.toast = function(msg,cls,ms){ var w=$('toasts'); var t=document.createElement('div'); t.className='toast '+(cls||''); t.textContent=msg; w.appendChild(t); requestAnimationFrame(function(){ t.classList.add('show'); }); setTimeout(function(){ t.classList.remove('show'); setTimeout(function(){ t.remove(); },300); },ms||2600); };
D.ev = function(id){ return D.S.events.filter(function(e){return e.id===id;})[0]; };
