/* ── threat model: only confirmed and reported events move the needle ── */
D.SEVW = [0,1,2,4,7,11];
D.threat = function(asOf){ var t=asOf?dnum(asOf):Date.now(); var dom={}, tot=0; Object.keys(D.DOMAIN).forEach(function(k){ dom[k]=0; });
  var counted=0, noise=0, recent=0;
  D.S.events.forEach(function(e){ var age=(t-dnum(e.date))/DAY; if(age<-0.5) return; var st=D.STATUS[e.status]||D.STATUS.UNVERIFIED;
    if(age<=14){ recent++; if(!st.w) noise++; }
    if(!st.w||age>120) return; var w=st.w*D.SEVW[e.sev||1]*Math.pow(.5,age/14); counted++;
    Object.keys(D.DOMAIN).forEach(function(k){ if(D.DOMAIN[k].cats.indexOf(e.cat)>=0){ dom[k]+=w*(k==='political'?.4:1); tot+=w*(k==='political'?.4:1); } }); });
  var sc=function(v,k){ return Math.round(100*(1-Math.exp(-v/k))); };
  var out={score:sc(tot,52),dom:{},counted:counted,noise:recent?noise/recent:0,recent:recent,noiseN:noise};
  Object.keys(dom).forEach(function(k){ out.dom[k]=sc(dom[k],18); });
  out.level=D.LEVELS.filter(function(l){return out.score<l.max;})[0]; return out; };
D.trend = function(days){ var a=[]; for(var i=days-1;i>=0;i--){ var d=new Date(Date.now()-i*DAY).toISOString().slice(0,10); a.push({d:d,v:D.threat(d).score}); } return a; };
D.gauge = function(T){ var segs=D.LEVELS.map(function(l,i){ var a0=Math.PI*(1-(i?D.LEVELS[i-1].max:0)/100), a1=Math.PI*(1-Math.min(100,l.max)/100); var r=80,cx=100,cy=96; var x0=cx+r*Math.cos(a0),y0=cy-r*Math.sin(a0),x1=cx+r*Math.cos(a1),y1=cy-r*Math.sin(a1); return '<path d="M'+x0.toFixed(1)+' '+y0.toFixed(1)+' A'+r+' '+r+' 0 0 1 '+x1.toFixed(1)+' '+y1.toFixed(1)+'" fill="none" stroke="var('+l.col+')" stroke-width="13" opacity="'+(l===T.level?1:.28)+'"/>'; }).join('');
  var a=Math.PI*(1-T.score/100); var nx=100+70*Math.cos(a), ny=96-70*Math.sin(a), mx=100+50*Math.cos(a), my=96-50*Math.sin(a);
  return '<svg class="gauge" viewBox="0 0 200 108" role="img" aria-label="Threat score '+T.score+' of 100, level '+T.level.name+'">'+segs+'<line x1="'+mx.toFixed(1)+'" y1="'+my.toFixed(1)+'" x2="'+nx.toFixed(1)+'" y2="'+ny.toFixed(1)+'" stroke="var(--txh)" stroke-width="3.5" stroke-linecap="round"/><text x="100" y="92" text-anchor="middle" font-family="Orbitron,monospace" font-weight="700" font-size="26" fill="var(--txh)">'+T.score+'</text></svg>'; };

/* ── shell ── */
